from fractions import Fraction

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def generate_cnf(n):
        clauses = []
        for _ in range(2 * n):
            clause = [random.randint(-n, -1), random.randint(1, n)]
            clauses.append(clause)
        return clauses

    def cnf_to_matrix(cnf, n):
        A = [[0] * (n + 1) for _ in range(n + 1)]
        for clause in cnf:
            x, y = abs(clause[0]), abs(clause[1])
            if clause[0] < 0:
                A[x][y] += 1
            else:
                A[y][x] += 1
        return A

    def gaussian_elimination(A):
        n = len(A)
        for i in range(n):
            max_row = i
            for j in range(i + 1, n):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            if A[i][i] == 0:
                return None
            for j in range(i + 1, n):
                factor = Fraction(A[j][i], A[i][i])
                for k in range(n + 1):
                    A[j][k] -= factor * A[i][k]
        return A

    def hodge_span_width(A):
        rank = 0
        for row in gaussian_elimination(A):
            if any(row):
                rank += 1
        return rank

    def resolution_proof_width(cnf, n):
        stack = [cnf[:]]
        while stack:
            clause = stack.pop()
            if not clause:
                continue
            literal = random.choice(clause)
            new_clauses = []
            for c in cnf:
                if literal in c and -literal in c:
                    continue
                if literal in c:
                    new_clauses.append([x for x in c if x != literal])
                elif -literal in c:
                    new_clauses.append([x for x in c if x != -literal])
            stack.extend(new_clauses)
        return len(cnf) - len(stack)

    n = random.randint(5, 30)
    cnf = generate_cnf(n)
